# exec'd from build.py after tools_pages.py; builds /directory/
import csv
MAIL="tapelog@mail.grokbot.com"
CATS={"journals":"Trading journals","charting":"Charting & trading platforms","screeners":"Screeners, scanners & news","brokers":"Brokers","prop-firms":"Prop firms (funded trader programs)","data-apis":"Market data & APIs","backtesting":"Backtesting","education":"Education","calculators":"Free calculators"}
ENT=[dict(name=r[0],url=r[1],cat=r[2],price=r[3],tags=r[4].split(","),desc=r[5]) for r in csv.reader(open(f"{OUT}/data/tools.tsv"),delimiter="\t") if r]
for s,h,d in TOOLS: ENT.append(dict(name=html.unescape(h).replace("calculator","Calculator")+" (TapeLog)",url=f"{BASE}/tools/{s}/",cat="calculators",price="Free",tags=["calculator","in-browser","tapelog"],desc=html.unescape(d).split(":")[0]+"."))
SUBMIT=f'mailto:{MAIL}?subject=Submit%20a%20tool%20to%20the%20TapeLog%20directory&body=Tool%20name%3A%0AURL%3A%0ACategory%3A%0AOne-line%20description%3A%0AFree%2Fpaid%3A'
DCSS="<style>.dir{list-style:none;padding:0}.dir li{border:1px solid #dde3ea;border-radius:8px;padding:10px 14px;margin:8px 0}.tag{display:inline-block;background:#eef3f8;border-radius:10px;padding:0 8px;margin:2px;font-size:.78em}.feat{border:2px dashed #f0b400;border-radius:10px;padding:14px;margin:16px 0;background:#fffbef}#q{font:inherit;padding:10px;width:100%;border:1px solid #c9d3dd;border-radius:8px}.chips a{margin-right:10px}</style>"
def li(e): return f'<li data-s="{html.escape((e["name"]+" "+e["desc"]+" "+" ".join(e["tags"])+" "+e["cat"]).lower())}" data-c="{e["cat"]}"><a href="{e["url"]}" rel="nofollow noopener" target="_blank"><b>{html.escape(e["name"])}</b></a> <span class="small">· {html.escape(e["price"])}</span><br>{html.escape(e["desc"])}<br>{"".join(f"<span class=tag>{html.escape(t)}</span>" for t in e["tags"])}</li>'
def il(es,nm): return {"@context":"https://schema.org","@type":"ItemList","name":nm,"numberOfItems":len(es),"itemListElement":[{"@type":"ListItem","position":i+1,"name":e["name"],"url":e["url"],"description":e["desc"]} for i,e in enumerate(es)]}
FEAT=f'<div class="feat"><b>Featured</b>. <em>Sponsored spots available.</em> Put your trading tool here. <a href="/tapelog/directory/advertise/">See sponsorship options</a>.</div>'
chips='<p class="chips">'+"".join(f'<a href="/tapelog/directory/{c}/">{n}</a>' for c,n in CATS.items())+'</p>'
FOOT=f'<p><a class="btn alt" href="{SUBMIT}">Submit a tool</a> <a class="btn alt" href="https://thetapelog.beehiiv.com/subscribe">Get the free newsletter</a></p><p class="small">Listings are editorial, neutral and free. Prices/plans change, so check each vendor. Links are plain links, not affiliate links. TapeLog\'s own products are marked "(TapeLog)" or "this site\'s own". Inclusion is not an endorsement or financial advice.</p>'
JS="<script>const q=document.getElementById('q');q.addEventListener('input',()=>{const t=q.value.toLowerCase().trim();let n=0;document.querySelectorAll('.dir li').forEach(l=>{const ok=!t||t.split(/\\s+/).every(w=>l.dataset.s.includes(w));l.style.display=ok?'':'none';if(ok)n++});document.getElementById('n').textContent=n;document.querySelectorAll('.dir').forEach(u=>{const h=u.previousElementSibling;if(h&&h.tagName==='H2')h.style.display=[...u.children].some(l=>l.style.display!=='none')?'':'none'})});</script>"
body=f'{DCSS}<h1>Trading tools directory</h1><p>{len(ENT)} hand-picked tools for active traders: journals, charting, screeners, brokers, prop firms, data APIs, backtesting and education. Every link was checked on {TODAY}.</p>{FEAT}<input id="q" type="search" placeholder="Search tools, e.g. futures, free, python, journal" aria-label="Search tools"><p class="small"><span id="n">{len(ENT)}</span> tools shown</p>{chips}'
for c,n in CATS.items():
    es=[e for e in ENT if e["cat"]==c]; body+=f'<h2 id="{c}"><a href="/tapelog/directory/{c}/">{n}</a> ({len(es)})</h2><ul class="dir">'+"".join(map(li,es))+"</ul>"
DFAQ=[("What is the TapeLog trading tools directory?",f"A free, neutral list of {len(ENT)} trading tools across journals, charting, screeners, brokers, prop firms, market data, backtesting and education."),("How do I add my tool?",f"Email {MAIL} with the name, URL, category and a one-line description. Standard listings are free."),("Are these affiliate links?","No. Links are plain links. Featured slots, when sold, are clearly labeled Sponsored.")]
page("/directory/",f"Trading Tools Directory 2026: {len(ENT)} Journals, Screeners, Brokers & More | TapeLog","Free directory of trading tools: journals, charting platforms, screeners, brokers, prop firms, market data APIs, backtesting and education. Search and filter by tag.",body+FOOT+"<h2>FAQ</h2>"+faq_html(DFAQ)+JS,[il(ENT,"Trading tools directory"),faq_ld(DFAQ)])
for c,n in CATS.items():
    es=[e for e in ENT if e["cat"]==c]
    page(f"/directory/{c}/",f"{n}: {len(es)} Tools Compared (2026) | TapeLog Directory",f"{n} for traders: {', '.join(e['name'] for e in es[:5])} and more, with free/paid notes and tags.",
      f'{DCSS}<p class="small"><a href="/tapelog/directory/">Directory</a> › {n}</p><h1>{n}</h1><p>{len(es)} listings. Neutral one-line summaries and pricing notes; verify current pricing with each vendor.</p>{FEAT}<ul class="dir">'+"".join(map(li,es))+"</ul>"+chips+FOOT,[il(es,n)])
adv=f"""<h1>Advertise in the TapeLog trading tools directory</h1><p>Reach active day traders who are comparing journals, platforms, data and education. Sponsored placements are always labeled <b>Sponsored</b>; editorial listings stay free and neutral.</p>
<table><tr><th>Placement</th><th>Price</th><th>What you get</th></tr>
<tr><td>Featured listing</td><td>$49/month</td><td>Your tool in the Featured slot on the main directory page, labeled Sponsored, with logo, one-line pitch and link.</td></tr>
<tr><td>Category sponsor</td><td>$99/month</td><td>Top Featured slot on one category page (e.g. Trading journals or Prop firms), plus the main-page Featured slot.</td></tr>
<tr><td>Newsletter sponsor</td><td>Ask</td><td>A labeled sponsor block in The TapeLog weekly newsletter.</td></tr></table>
<h2>Rules</h2><ul><li>Sponsored placements are labeled as such. No hidden paid rankings.</li><li>We don't accept guaranteed-returns, signal-selling or unregistered-investment offers.</li><li>Monthly, cancel anytime. Placement goes live after we review your tool.</li></ul>
<p><a class="btn" href="mailto:{MAIL}?subject=TapeLog%20directory%20sponsorship">Email {MAIL}</a></p><p class="small">Want a free standard listing instead? <a href="{SUBMIT}">Submit a tool</a>.</p>"""
page("/directory/advertise/","Advertise to Day Traders: Sponsored Directory Listings | TapeLog","Sponsor the TapeLog trading tools directory: featured listing $49/month, category sponsor $99/month, newsletter sponsorships. Clearly labeled placements.",adv)
